using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryRenewalTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-held/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true,bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=policy?NewGameMilitary.UnitCommandHoldingContract:null},s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static WorldSession HomeReady(){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(ArmyEnd(s),j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static TroopDispatch Query(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();
    static TroopReceipt Answer(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();
    static UnitPostInquiryAnswer Quote(ContractWorld w){var r=w.NewMilitary!.UnitInquiry!.Receipts.Last();return ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body));}
    static void Ask(WorldSession s,NewMilitaryAction action=NewMilitaryAction.InquireUnitKnown,bool policy=true){var r=s.DecideNewMilitary(Input(s,action) with{PostPolicy=policy?NewGameMilitary.UnitReplyRecoveryContract:null},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void MoveAway(WorldSession s){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);}
    static WorldSession FailedReply(bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Ask(s,policy:policy);At(s,Query(s).DueAt);MoveAway(s);At(s,Answer(s).ReplyDueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Replies.Last().Received);return s;}
    static void AtPersonEnd(WorldSession s){var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);}
    static void WalkTo(WorldSession s,FieldPoint p){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=p},s.PlayerControl,s.Revision).Code);AtPersonEnd(s);}
    static WorldSession AtHeldOriginal(bool retryFirst=false){var s=FailedReply();var report=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single();if(retryFirst)Send(s,NewMilitaryAction.PersonalHome);At(s,report.DueAt);if(retryFirst)At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last().DueAt);WalkTo(s,Query(s).Destination);return s;}
    static WorldSession AtMissedReport(){var s=HomeReady();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+5000,a.Y),B=new(a.X+5000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);long start=s.Seconds;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);var w=s.DiagnosticSnapshot();var known=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(NewGameMilitary.PersonPosition(w,s.Seconds),known,s.Seconds,courier:true,atlas:true);long delay=Math.Max(1,(path.LastOrDefault()?.EndAt??s.Seconds)-s.Seconds);long send=start+9-delay;Assert.True(send>=s.Seconds,"fixture must reach home before the last pre-rout inquiry window");At(s,send);Ask(s);At(s,Query(s).DueAt);Assert.True(Answer(s).Delivered);MoveAway(s);At(s,Answer(s).ReplyDueAt);var report=Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights);At(s,report.DueAt);var journey=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(s.Seconds,(journey.Route.LastOrDefault()?.EndAt??s.Seconds)+1));return s;}
    static TroopDispatch Original(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();
    static WorldSession MissedFailureReport(){var s=Failed(false);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single();MoveAway(s);At(s,r.ReplyDueAt);AtPersonEnd(s);return s;}
    static TroopDispatch Cancel(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Dispatches.Last();
    static void Recall(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=NewGameMilitary.UnitCommandHoldingContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},s.PlayerControl,s.Revision).Code);
    static void CancelSend(WorldSession s,long? effective=null,NewMilitaryAction action=NewMilitaryAction.CancelRecallHome)=>Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,action) with{TargetOriginal=Original(s).Id,RequestedEffectiveAt=effective,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},s.PlayerControl,s.Revision).Code);
    static void Restore(WorldSession s,long until){var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));At(s,until);At(c,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    static void Finish(WorldSession s,bool open=true){var w=s.DiagnosticSnapshot();if(NewGameMilitary.Detached(w))Send(s,NewMilitaryAction.Attach);if(NewGameMilitary.UnitCarries(s.DiagnosticSnapshot()))Send(s,NewMilitaryAction.Reclaim);if(NewGameMilitary.Deployed(s.DiagnosticSnapshot())){Send(s,NewMilitaryAction.Recall);At(s,ArmyEnd(s)+1);Send(s,NewMilitaryAction.Enter);}long carry=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;if(carry>0)Send(s,NewMilitaryAction.Unload,carry);Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);if(open)Open(s);}
    static void Again(WorldSession s,bool pickup=true){Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanRequest);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).CanPickup);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);if(pickup)Send(s,NewMilitaryAction.Pickup);}
    [Fact]public void SecondLoanPreservesLifetimeStockAndSameRealGarrison(){var s=Ready();Finish(s);var first=s.DiagnosticSnapshot();var units=first.Units.Select(u=>u.Id).ToArray();var messages=first.Messaging.Messages.ToArray();long spent=first.NewMilitary!.Uses.Sum(u=>u.Consumed);Again(s);var w=s.DiagnosticSnapshot();Assert.Equal(2,NewGameMilitary.Cases(w).Length);Assert.Equal(units,w.Units.Select(u=>u.Id).ToArray());Assert.Equal(NewGameMilitary.InitialStock-spent,w.ResourceLots.Sum(l=>l.Quantity));Assert.All(messages,m=>Assert.Equal(m,w.Messaging.Messages.Single(x=>x.Id==m.Id)));Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);Restore(s,s.Seconds+5);}
    [Fact]public void ActualReturnDoesNotExposeRenewalUntilNoticeIsOpened(){var s=Ready();Finish(s,false);Assert.Contains(s.DiagnosticSnapshot().NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).CanRequest);Open(s);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanRequest);Again(s);Restore(s,s.Seconds+1);}
    [Theory][InlineData(false)][InlineData(true)]public void MissingOrUnknownRenewalContractIsAtomic(bool unknown){var s=Ready();Finish(s);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=unknown?"unknown":null},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void OldInputRemainsGloballyIdempotentAcrossCases(){var s=Ready();var old=s.DiagnosticSnapshot().NewMilitary!.Requests.First().Input;Finish(s);Again(s);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(old,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideNewMilitary(old with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);Restore(s,s.Seconds+1);}
    [Fact]public void OldLateOriginalCanBeReceivedButCannotCommandNewLoan(){var s=Failed();var old=Original(s);Finish(s);Again(s);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);int orders=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.DeliverHeldRecallHome);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.Single(w.Messaging.Receipts,r=>r.MessageId==old.Message);Assert.True(w.NewMilitary!.CommandHolding!.Outcomes.Last().Received);Assert.False(w.NewMilitary.CommandHolding.Outcomes.Last().Applied);Assert.Equal(orders,w.NewMilitary.Orders.Length);Restore(s,s.Seconds+10);}
    [Fact]public void PriorFutureCancelCannotStopNewLoanEvenWithFreshCustody(){var s=HomeReady();Recall(s);long effective=s.Seconds+100;CancelSend(s,effective);At(s,Cancel(s).DueAt);Finish(s);Again(s);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);Send(s,NewMilitaryAction.Hold);var id=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Id;At(s,effective);var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.AuthorityEnded,w.NewMilitary!.Cancellation!.Effects.Single().Outcome);Assert.Equal(id,w.NewMilitary.Orders.Last().Id);Assert.DoesNotContain("取消返書",NewGameMilitary.CancellationStatus(w));Restore(s,s.Seconds+10);}
    [Fact]public void OldReportCannotCompleteNewUnreportedHandover(){var s=Ready();Finish(s);Again(s);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);var w=s.DiagnosticSnapshot();Assert.Equal(1,w.NewMilitary!.Events.Count(e=>e.Effect==MilitaryEffect.Returned));Send(s,NewMilitaryAction.Report);At(s,s.Seconds+3);Assert.Equal(2,s.DiagnosticSnapshot().NewMilitary!.Events.Count(e=>e.Effect==MilitaryEffect.Returned));Restore(s,s.Seconds+2);}
    [Fact]public void CombatCasualtiesAndSpentFoodSurviveSecondPickup(){var s=Ready();Send(s,NewMilitaryAction.Recall);At(s,ArmyEnd(s)+1);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);At(s,s.Seconds+3);Send(s,NewMilitaryAction.CombatEnd);var survivors=s.DiagnosticSnapshot().Units.Select(u=>u.Soldiers).ToArray();Assert.True(survivors.Sum()<100);Finish(s);long spent=s.DiagnosticSnapshot().NewMilitary!.Uses.Sum(u=>u.Consumed);Again(s);var w=s.DiagnosticSnapshot();Assert.Equal(survivors,w.Units.Select(u=>u.Soldiers).ToArray());Assert.Equal(NewGameMilitary.InitialStock-spent,w.ResourceLots.Sum(l=>l.Quantity));Assert.False(NewGameMilitary.CanStartCombat(w));Restore(s,s.Seconds+3);}
    [Fact]public void ExpiredUnpickedOfferCanStartDistinctNewCase(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,s.Seconds+2);Open(s);At(s,s.Seconds+NewGameMilitary.OfferSeconds+2);Open(s);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanRequest);Again(s);Assert.Equal(2,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Length);Restore(s,s.Seconds+2);}
    [Fact]public void EarlierOpenedPermissionDoesNotGrantSecondCasePickup(){var s=Ready();Finish(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).CanPickup);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Pickup),s.PlayerControl,s.Revision).Code);Open(s);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanPickup);Send(s,NewMilitaryAction.Pickup);Restore(s,s.Seconds+2);}
    [Theory][InlineData(0)][InlineData(1)]public void ForgedCaseContractOrRepeatedPermissionIsRejected(int kind){var s=Ready();Finish(s);Again(s);var w=s.DiagnosticSnapshot();var n=w.NewMilitary!;if(kind==0){int i=Array.FindLastIndex(n.Requests,q=>q.Input.Action==NewMilitaryAction.Request);n.Requests[i]=n.Requests[i] with{Input=n.Requests[i].Input with{CycleContract=null}};}else{var e=n.Events.Last(e=>e.Effect==MilitaryEffect.Permission);w.NewMilitary=n with{Events=[..n.Events,e]};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void RenewalBoundariesRestoreSameFuture(int phase){var s=Ready();Finish(s);if(phase>0){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);}if(phase>1)At(s,s.Seconds+1);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c}){if(phase==0)Assert.Equal(ResultCode.Accepted,x.DecideNewMilitary(Input(x,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},x.PlayerControl,x.Revision).Code);At(x,x.Seconds+2);Open(x);Send(x,NewMilitaryAction.Accept);At(x,x.Seconds+2);Open(x);Send(x,NewMilitaryAction.Pickup);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Fact]public void ThreeCasesPreserveOneLifetimeLedgerAndUniqueCaseRoots(){var s=Ready();Finish(s);Again(s);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);At(s,s.Seconds+3);Finish(s);Again(s);var w=s.DiagnosticSnapshot();Assert.Equal(3,NewGameMilitary.Cases(w).Length);Assert.Equal(3,NewGameMilitary.Cases(w).Select(c=>c.Id).Distinct().Count());Assert.Equal(NewGameMilitary.InitialStock-w.NewMilitary!.Uses.Sum(u=>u.Consumed),w.ResourceLots.Sum(l=>l.Quantity));Assert.Equal(2,w.NewMilitary.Events.Count(e=>e.Effect==MilitaryEffect.Returned));Restore(s,s.Seconds+2);}
    [Fact]public void OldSingleCaseInputDoesNotGainNewField(){var s=Ready();var w=s.DiagnosticSnapshot();Assert.DoesNotContain("CycleContract",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));Restore(s,s.Seconds+2);}
    [Fact]public void ActiveDutyCannotStartOverEvenWithCorrectRenewalFlag(){var s=Ready();string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).CanRequest);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void FirstCaseCannotPretendToBeRenewal(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void OldInquiryArrivingAfterNewRequestKeepsOldCaseAndCannotCloseNewOne(){var s=Ready();Finish(s);var old=NewGameMilitary.Cases(s.DiagnosticSnapshot()).Single().Id;Send(s,NewMilitaryAction.Inquire);var inquiry=s.DiagnosticSnapshot().NewMilitary!.Requests.Last();Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{CycleContract=NewGameMilitary.RenewalContract},s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);var w=s.DiagnosticSnapshot();var e=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.StatusSent&&e.Source==inquiry.Message);Assert.Equal(old.Value,w.Messaging.Messages.Single(m=>m.Id==e.Message).CorrelationId);Assert.True(NewGameMilitary.View(w).CanAccept);Assert.False(NewGameMilitary.View(w).CanRequest);Assert.DoesNotContain("指揮返還の通知を確認",NewGameMilitary.View(w).Status);Restore(s,s.Seconds+2);}
    [Fact]public void QuotedReturnPermitsRenewalWithoutOpeningOriginalNotice(){var s=Ready();Finish(s,false);var original=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.Returned);Send(s,NewMilitaryAction.Inquire);var request=s.DiagnosticSnapshot().NewMilitary!.Requests.Last();At(s,s.Seconds+2);var w=s.DiagnosticSnapshot();var quote=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.StatusSent&&e.Source==request.Message);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(quote.Message),s.Revision).Code);Assert.DoesNotContain(s.DiagnosticSnapshot().NewMilitary!.Openings,o=>o.Message==original.Message);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,original.Message,s.PlayerControl.Value));Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanRequest);Again(s);Restore(s,s.Seconds+2);}
    [Fact]public void QuotedExpiryPermitsNewCaseWithoutPretendingOriginalWasOpened(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);At(s,s.Seconds+NewGameMilitary.OfferSeconds+2);var original=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.Expired);Send(s,NewMilitaryAction.Inquire);var request=s.DiagnosticSnapshot().NewMilitary!.Requests.Last();At(s,s.Seconds+2);var quote=s.DiagnosticSnapshot().NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.StatusSent&&e.Source==request.Message);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(quote.Message),s.Revision).Code);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,original.Message,s.PlayerControl.Value));Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).CanRequest);Again(s);Restore(s,s.Seconds+2);}
}
